mapper.update:
UPDATE car
SET discnt_at = NOW(),
    discnt_owner_id = #{ownerId}
WHERE car_id = #{carId}

mapper.select:
SELECT m.car_num, c.spc_no, c.ent_time, c.car_stat, c.discnt_at, c.cost, c.id, m.name, m.car_type, m.auth FROM car c JOIN member m ON c.id = m.id
c.car_stat <> 2
AND c.id = #{keyword}
AND m.name = #{keyword}
AND m.car_num LIKE CONCAT('%', #{keyword}, '%')
ORDER BY c.ent_time DESC LIMIT 10 OFFSET (#{pageNum} - 1) * 10

SELECT count(*) FROM car c JOIN member m ON c.id = m.id
c.car_stat <> 2
AND c.id = #{keyword}
AND m.name = #{keyword}
AND m.car_num LIKE CONCAT('%', #{keyword}, '%')

